  /// 获取指定键的文字（使用当前语言）
  static String get(String key) {
    return _strings[currentLanguage]?[key] ??
        _strings['en']?[key] ??
        _strings['zh']?[key] ??
        key; // 如果都找不到，返回键名本身
  }

  /// 获取指定语言和键的文字
  static String getWithLanguage(String language, String key) {
    return _strings[language]?[key] ??
        _strings['en']?[key] ??
        _strings['zh']?[key] ??
        key;
  }

  /// 设置当前语言
  static void setLanguage(String language) {
    if (_strings.containsKey(language)) {
      currentLanguage = language;
    }
  }

  /// 获取当前语言
  static String getLanguage() {
    return currentLanguage;
  }

  /// 获取所有支持的语言列表
  static List<String> getSupportedLanguages() {
    return _strings.keys.toList();
  }

  /// 所有语言的文案表（只读），供错误文案等展示层判断某段文字是否已本地化。
  static Map<String, Map<String, String>> get allTables => _strings;

  /// 仅供测试检查各语言 key、占位符是否一致，业务代码请使用 [get]。
  @visibleForTesting
  static Map<String, Map<String, String>> get tablesForTesting => _strings;
}
